actions.script:
ec.entity.find("moqui.adk.AdkAgentConfig").condition("enabled", "Y").list().each {
    it.set("enabled", "N").store()
}
def existing = ec.entity.find("moqui.adk.AdkAgentConfig").condition("adkServerUrl", adkServerUrl).one()
if (existing) {
    existing.set("description", description).set("enabled", "Y").store()
} else {
    ec.entity.makeValue("moqui.adk.AdkAgentConfig")
        .setSequencedIdPrimary()
        .set("adkServerUrl", adkServerUrl)
        .set("description", description ?: "ADK Server")
        .set("enabled", "Y")
        .create()
}
